const express = require('express');
const { Pool } = require('pg');
const app = express();

// Lazily-initialised pool so the module can be imported in tests
// without requiring a live DATABASE_URL.
let _pool = null;
function getPool() {
  if (!_pool) {
    _pool = new Pool({ connectionString: process.env.DATABASE_URL });
  }
  return _pool;
}

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Readiness probe — used by the k8s readiness probe.
// Returns 200 {"db":"ok"} when Postgres is reachable, 503 otherwise.
app.get('/healthz', async (req, res) => {
  try {
    await getPool().query('SELECT 1');
    res.status(200).json({ db: 'ok' });
  } catch (err) {
    console.error('Healthz DB check failed:', err.message);
    res.status(503).json({ db: 'error' });
  }
});

app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

app.listen(3000, () => {
  console.log('Server running on port 3000');
});

module.exports = app;

