app.get('/healthz', async (req, res) => {
  try {
    await checkDb();
    res.status(200).json({ db: 'ok' });
  } catch (err) {
    console.error('Health check failed:', err.message);
    res.status(503).json({ db: 'unreachable' });
  }
});

async function checkDb() {
  // Reuse an existing pool when available, otherwise create a one-off client
  // so the probe works with just DATABASE_URL in the environment.
  if (app.locals.dbPool) {
    const client = await app.locals.dbPool.connect();
    try {
      await client.query('SELECT 1');
    } finally {
      client.release();
    }
    return;
  }

  // Fallback: lightweight ad-hoc connection
  const { Client } = require('pg');
  const client = new Client({ connectionString: process.env.DATABASE_URL });
  await client.connect();
  try {
    await client.query('SELECT 1');
  } finally {
    await client.end();
  }
}

